/**
 * gen-industry-roles.mjs
 * ───────────────────────────────────────────────────────────────
 * 行业角色自生长生成器（可复用）
 *
 * 作用：把"AI 基于用户需求 + 行业知识补全后产出的角色规划 JSON"，
 *       批量落盘为符合九段式 + 隔离标记的 .md 角色文件，并写入
 *       对应 division 目录。生成的角色带 autoGenerated + scope 标记，
 *       绝不污染全局 447 包。
 *
 * 设计边界（遵循用户确认的机制）：
 *   - 内容由 AI 在调用本脚本前基于需求补全（联网/查库/口述优先级）
 *   - 本脚本只负责"结构化落盘 + 隔离 + 构建合规"，不做内容臆造
 *   - slug 强制 `行业前缀-角色名`，同名检测避免覆盖既有角色
 *   - scope 固定为 project:<projectId>，仅当前用户/项目可见
 *
 * 用法：
 *   node scripts/gen-industry-roles.mjs --plan plans/edu-roles.json
 *
 * 规划 JSON 结构：
 * {
 *   "division": "education",
 *   "divisionZh": "教育",
 *   "industryPrefix": "edu",
 *   "projectId": "zhuhui-smart-campus",
 *   "generatedFrom": "用户的需求聊天.txt + V16.xlsx",
 *   "roles": [
 *     {
 *       "slug": "edu-product-manager",
 *       "nameZh": "教务产品经理（B层租户侧）",
 *       "emoji": "🏫",
 *       "tags": ["教务SaaS", "租户侧产品"],
 *       "description": "...",
 *       "sections": {
 *         "identity": "...",        // 🧠 身份与记忆
 *         "mission": "...",         // 🎯 核心使命
 *         "rules": "...",           // 🚨 必须遵守的规则
 *         "deliverables": "...",    // 📋 技术交付物
 *         "workflow": "...",        // 🔄 工作流程
 *         "comms": "...",           // 💬 沟通风格
 *         "learning": "...",        // 📚 学习与记忆
 *         "success": "...",         // 🎯 成功标准
 *         "advanced": "..."         // 🚀 进阶能力
 *       }
 *     }
 *   ]
 * }
 */

import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, "..");
const DIVISION_ROOT = resolve(ROOT, "role-packs-src/zh-virmoon");

function parseArgs(argv) {
  const out = { plan: null };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "--plan") out.plan = argv[++i];
    else if (a === "--dry") out.dry = true;
  }
  return out;
}

const SECTION_TITLES = {
  identity: "🧠 身份与记忆",
  mission: "🎯 核心使命",
  rules: "🚨 必须遵守的规则",
  deliverables: "📋 技术交付物",
  workflow: "🔄 工作流程",
  comms: "💬 沟通风格",
  learning: "📚 学习与记忆",
  success: "🎯 成功标准",
  advanced: "🚀 进阶能力",
};

const SECTION_ORDER = [
  "identity", "mission", "rules", "deliverables",
  "workflow", "comms", "learning", "success", "advanced",
];

function buildFrontmatter(role, meta) {
  const fm = [
    `id: "${meta.industryPrefix}-auto-${String(role._idx).padStart(4, "0")}"`,
    `slug: ${role.slug}`,
    `nameZh: "${role.nameZh}"`,
    `division: ${meta.division}`,
    `divisionZh: "${meta.divisionZh}"`,
    `emoji: "${role.emoji || "🏢"}"`,
    `roleKind: worker`,
    `brainSlot: work`,
    `kickoffWave: planning`,
    `tags: ${JSON.stringify(role.tags || [])}`,
    `description: "${role.description}"`,
    `source: "${meta.division}/${role.slug}.md"`,
    `autoGenerated: true`,
    `scope: "project:${meta.projectId}"`,
    `generatedFrom: "${meta.generatedFrom}"`,
  ];
  return `---\n${fm.join("\n")}\n---`;
}

function buildBody(role) {
  const lines = [`# ${role.nameZh}`, "", role.opening || `你是**${role.nameZh}**，属于 ${role.divisionZh} 行业的租户侧角色，由系统基于用户需求自动生成。`];
  for (const key of SECTION_ORDER) {
    const content = role.sections?.[key];
    if (!content) continue;
    lines.push("", `## ${SECTION_TITLES[key]}`, "", content.trim());
  }
  return lines.join("\n");
}

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (!args.plan) {
    console.error("用法: node scripts/gen-industry-roles.mjs --plan <规划JSON路径> [--dry]");
    process.exit(2);
  }
  const planPath = resolve(ROOT, args.plan);
  if (!existsSync(planPath)) {
    console.error(`规划文件不存在: ${planPath}`);
    process.exit(2);
  }
  const plan = JSON.parse(readFileSync(planPath, "utf8"));
  const meta = {
    division: plan.division,
    divisionZh: plan.divisionZh,
    industryPrefix: plan.industryPrefix,
    projectId: plan.projectId,
    generatedFrom: plan.generatedFrom,
  };
  const targetDir = resolve(DIVISION_ROOT, plan.division);
  if (!existsSync(targetDir)) mkdirSync(targetDir, { recursive: true });

  let created = 0;
  let skipped = 0;
  const createdSlugs = [];

  plan.roles.forEach((role, i) => {
    role._idx = i + 1;
    // 同名检测：不覆盖既有角色
    const dest = resolve(targetDir, `${role.slug}.md`);
    if (existsSync(dest)) {
      console.warn(`  ⚠ 跳过已存在角色: ${role.slug}（不覆盖）`);
      skipped++;
      return;
    }
    const md = `${buildFrontmatter(role, meta)}\n\n${buildBody(role)}\n`;
    if (args.dry) {
      console.log(`  [dry] 将生成: ${plan.division}/${role.slug}.md`);
    } else {
      writeFileSync(dest, md, "utf8");
      console.log(`  ✓ 生成: ${plan.division}/${role.slug}.md`);
    }
    createdSlugs.push(role.slug);
    created++;
  });

  console.log(`\n完成：新建 ${created} 个，跳过 ${skipped} 个（已存在）。`);
  if (!args.dry && createdSlugs.length) {
    console.log("新建 slug:", createdSlugs.join(", "));
    console.log("\n下一步: 运行 build-role-pack.mjs 重建并校验九段合规。");
  }
}

main();
